export default "/* ==========================================================================\n   Preview Component Tokens\n   --------------------------------------------------------------------------\n   Only preview-specific visual roles receive component tokens. Generic\n   surfaces, text, borders, and shadows consume semantic tokens directly.\n   ========================================================================== */\n\n:host {\n  --preview-badge-foreground: var(--primary-foreground);\n  --preview-badge-border: color-mix(in srgb, var(--primary-foreground) 22%, transparent);\n  --preview-badge-background: linear-gradient(135deg, var(--layout-selection), var(--layout-role-both));\n  --preview-badge-shadow: 0 6px 18px color-mix(in srgb, var(--layout-selection) 28%, transparent);\n  display: block;\n  width: 100%;\n  min-width: 0;\n  height: 100%;\n}\n\n/* Preview Root and Box Sizing\n   ========================================================================== */\n\n#preview-root {\n  position: relative;\n  width: 100%;\n  min-width: 0;\n  height: 100%;\n  box-sizing: border-box;\n  background: var(--background);\n  color: var(--foreground);\n}\n\n#preview-root *,\n#preview-root *::before,\n#preview-root *::after {\n  box-sizing: border-box;\n}\n\n/* Editor Interaction Targets\n   ========================================================================== \n *\n * Every editor-managed element can be selected.\n *\n * Don't give every element a permanent outline because\n * that makes the preview impossible to read.\n */\n[data-editor-id] {\n  position: relative;\n  transition:\n    outline-color 140ms ease,\n    box-shadow 140ms ease,\n    filter 140ms ease;\n}\n\n/* Layout Role Defaults\n   ========================================================================== \n *\n * Theme defaults apply only after dynamic role metadata is attached.\n * Preset CSS is injected after this stylesheet, so authored background,\n * border, color and shadow declarations naturally override these values.\n */\n:where([data-layout-role=\"container\"]) {\n  border: 1px solid var(--border);\n  color: var(--foreground);\n  box-shadow: var(--shadow-md);\n}\n\n:where([data-layout-role=\"item\"]),\n:where([data-layout-role=\"both\"]) {\n  border: 1px solid var(--border);\n  color: var(--foreground);\n  box-shadow: var(--shadow-sm);\n}\n\n/* Hover and Selection\n   ========================================================================== */\n\n[data-editor-id]:not(.preview-selected):hover {\n  outline: 1px solid color-mix(in srgb, var(--layout-role-container) 75%, transparent) !important;\n  outline-offset: -1px;\n  box-shadow: inset 0 0 0 9999px color-mix(in srgb, var(--layout-role-container) 5%, transparent);\n  cursor: pointer;\n}\n\n[data-editor-id].preview-selected {\n  outline: 2px solid var(--layout-selection) !important;\n  outline-offset: 2px;\n  box-shadow:\n    0 0 0 1px color-mix(in srgb, var(--layout-selection) 26%, transparent),\n    0 0 22px color-mix(in srgb, var(--layout-selection) 32%, transparent) !important;\n}\n\n/* Selected Role Badge\n   ========================================================================== */\n\n[data-editor-id].preview-selected::before {\n  content: attr(data-layout-role);\n  position: absolute;\n  z-index: 2147483647;\n  top: -15px;\n  right: 8px;\n  padding: 4px 8px;\n  border-radius: 999px;\n  border: 1px solid var(--preview-badge-border);\n  background: var(--preview-badge-background);\n  color: var(--preview-badge-foreground);\n  box-shadow:\n    var(--preview-badge-shadow),\n    inset 0 1px 0 color-mix(in srgb, var(--preview-badge-foreground) 18%, transparent);\n  font:\n    700 9px/1.4 ui-sans-serif,\n    system-ui,\n    sans-serif;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  pointer-events: none;\n  isolation: isolate;\n}\n\n[data-editor-id][data-layout-role=\"none\"].preview-selected::before {\n  display: none;\n}\n\n/* Selected Layout Roles\n   ========================================================================== \n *\n * Selected element establishes layout for children.\n */\n[data-editor-id].preview-layout-container {\n  outline-color: var(--layout-role-container) !important;\n  box-shadow:\n    0 0 0 1px color-mix(in srgb, var(--layout-role-container) 25%, transparent),\n    0 0 24px color-mix(in srgb, var(--layout-role-container) 26%, transparent) !important;\n}\n\n/*\n * Selected element participates in its parent's\n * flex/grid layout.\n */\n[data-editor-id].preview-layout-item {\n  outline-color: var(--layout-role-item) !important;\n  box-shadow:\n    0 0 0 1px color-mix(in srgb, var(--layout-role-item) 25%, transparent),\n    0 0 24px color-mix(in srgb, var(--layout-role-item) 25%, transparent) !important;\n}\n\n/*\n * The element is both:\n *\n * - a flex/grid item\n * - a flex/grid container\n */\n[data-editor-id].preview-layout-both {\n  outline-color: var(--layout-role-both) !important;\n  box-shadow:\n    0 0 0 1px color-mix(in srgb, var(--layout-role-both) 28%, transparent),\n    0 0 26px color-mix(in srgb, var(--layout-role-both) 30%, transparent) !important;\n}\n\n/* Related Parent and Sibling Elements\n   ========================================================================== */\n\n.preview-layout-parent {\n  outline: 1px dashed color-mix(in srgb, var(--layout-role-item) 85%, transparent) !important;\n  outline-offset: 6px;\n}\n\n[data-editor-id].preview-related-item {\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--layout-role-container) 55%, transparent);\n}\n\n[data-editor-id].preview-related-item::before {\n  content: \"\";\n  position: absolute;\n  z-index: 2147483646;\n  inset: 0;\n  background: linear-gradient(\n    135deg,\n    color-mix(in srgb, var(--layout-role-container) 8%, transparent),\n    color-mix(in srgb, var(--layout-selection) 5%, transparent)\n  );\n  pointer-events: none;\n}\n\n/* Layout Container Children\n   ========================================================================== \n *\n * Subtle visual indication of the children belonging\n * to the currently selected layout container.\n */\n[data-layout-container=\"flex\"] > [data-editor-id],\n[data-layout-container=\"inline-flex\"] > [data-editor-id] {\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--layout-role-container) 18%, transparent);\n}\n\n[data-layout-container=\"grid\"] > [data-editor-id],\n[data-layout-container=\"inline-grid\"] > [data-editor-id] {\n  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--layout-role-both) 18%, transparent);\n}\n"